<?php require_once 'bootstrap.php';$u=require_login();$sic=$_GET['event']??'';$fmt=strtoupper($_GET['format']??'A4');$st=db()->prepare('SELECT * FROM events WHERE sic_id=?');$st->execute([$sic]);$e=$st->fetch();if(!$e){http_response_code(404);exit('Evento non trovato');}$classes=['A4'=>'a4','A5'=>'a5','STORY'=>'story','SQUARE'=>'square'];$cl=$classes[$fmt]??'a4';?><!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($e['title'])?></title><style>*{box-sizing:border-box}body{margin:0;background:#070709;font-family:Arial,sans-serif}.sheet{margin:20px auto;background:linear-gradient(145deg,#070709,#181b22 58%,#D4AF37);color:white;position:relative;overflow:hidden;padding:8%;display:flex;flex-direction:column;justify-content:space-between;border:1px solid rgba(212,175,55,0.4)}.a4{width:210mm;height:297mm}.a5{width:148mm;height:210mm}.story{width:108mm;height:192mm}.square{width:180mm;height:180mm}.brand{font-size:24px;font-weight:900;letter-spacing:.18em;color:#D4AF37}.title{font-size:clamp(40px,8vw,84px);line-height:.92;font-weight:900;letter-spacing:-.06em;color:#FFFFFF}.meta{font-size:24px;font-weight:800;color:#FFF2B2}.sic{font-family:monospace;font-size:13px;color:#a1a1aa}.payoff{color:#FFF2B2;font-weight:900;letter-spacing:.12em}@media print{body{background:#fff}.sheet{margin:0;box-shadow:none}}</style></head><body><div class="sheet <?=$cl?>"><div><div class="brand">DEPENDEX</div><div class="payoff">AL CLUB. COL CLUB.</div></div><div><div class="title"><?=h($e['title'])?></div><p><?=h($e['description'])?></p></div><div><div class="meta"><?=h($e['starts_at'])?><br><?=h($e['venue'])?></div><p><?=h($e['comune'])?></p><div class="sic"><?=h($e['sic_id'])?></div></div></div><script>window.onload=()=>setTimeout(()=>window.print(),300)</script></body></html>